using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "MultipleTargetsCastStateJoystickAction", menuName = "Data/Battle/Actions/MultipleTargetsCastStateJoystickAction")]
public class MultipleTargetsCastStateJoystickAction : NoTargetSelectionCastStateJoystickAction
{
	protected override void HighlightTargets()
	{
		for (int i = 0; i < actionTargets.Count; i++)
		{
			actionTargets[i].GetComponentInChildren<TargetInstance>().OnMouseOver();
		}
	}

	protected override void CastAction()
	{
		AllTargetsCastAction();
	}
}
